mapper.select:
SELECT 
  FROM sys27_login_manage
       INNER JOIN sys01_company ON sys27_company_id = sys01_company_id
 WHERE CAST(sys27_company_id AS VARCHAR) LIKE #{companyId}
   AND CAST(sys27_person_id AS VARCHAR) LIKE #{personId}
 ORDER BY sys27_open_date, sys27_place_cd, sys27_mac_address

mapper.update:
UPDATE sys27_login_manage
   SET sys27_confirm_yn = #{confirmYn}
     , sys27_confirm_date = f_sysdate()
 WHERE sys27_login_manage_id = #{loginManageId}

